/**
 * Command of Evidence: Quantitative (coeq), rewritten to the Stellify question standard. The earlier tables used
 * invented numbers; every table and graph now reports figures published in the cited study (from its abstract or
 * its main results), and the passage states the study's own claim or a claim the figures directly test.
 */
import type { Figure, RawQuestion } from '@/lib/types';
import type { TrapCode } from '../distractors';

const CHECKED = '2026-11-27';
type Q = RawQuestion & { tags: (TrapCode | null)[] };
const COMPLETE = 'Which choice most effectively uses data from the table to complete the statement?';
const EXAMPLE = 'Which choice most effectively uses data from the table to complete the example?';
const GRAPH = 'Which choice best describes data from the graph that support the claim?';
const support = (who: string, what = 'claim') => `Which choice best describes data from the table that support ${who} ${what}?`;

interface Spec {
  id: string; d: RawQuestion['d']; sub: string; passage: string; figure: Figure; stem: string; choices: string[]; answer: number;
  tags: (TrapCode | null)[]; why: string[]; steps: string[]; cite: string; url: string; note: string;
}
function C(s: Spec): Q {
  return {
    id: s.id, skill: 'coeq', sub: s.sub, d: s.d, passage: s.passage, figure: s.figure, stem: s.stem, choices: s.choices,
    answer: s.answer, tags: s.tags, why: s.why, steps: s.steps,
    concept: 'Quantitative evidence questions ask for the specific data that bear on a stated claim, not merely data that are true.',
    strategy: 'Restate the claim in your own words, decide what comparison would test it, and find the choice that makes exactly that comparison with the right numbers.',
    trap: 'A choice that reports accurate numbers from the figure but does not address the claim, or that compares the wrong groups.',
    remember: 'Accurate is not enough: the right data must match what the claim is about.',
    meta: {
      source: { cite: s.cite, url: s.url, checked: CHECKED },
      review: {
        teacher: `AI teacher pass (Stellify): ${s.note}`,
        bias: 'AI bias and clarity pass (Stellify): the passage and figure supply all needed context, no outside knowledge or cultural, regional or income assumptions are required, and the wording is plain with no double negatives.',
        date: CHECKED,
      },
    },
  };
}

